<template>
  <scroll-view scroll-y class="page"><view v-if="loading" class="state">加载中...</view><view v-else-if="scissors"><view class="hero"><image :src="scissors.image||'/static/navigation/sravx-mark.png'" mode="aspectFit"/><text class="ui-strong">{{ scissors.name }}</text><text>{{ scissors.modelText }}</text></view><text class="heading">工具档案</text><view class="card archive"><view><text>型号</text><text>{{ scissors.modelText }}</text></view><view><text>SN编码</text><text>{{ scissors.sn }}</text></view><view><text>激活日期</text><text>{{ scissors.activationText }}</text></view><view><text>保修期</text><text class="ui-strong">{{ scissors.warrantyText }}</text></view></view><text class="heading">售后服务</text><view class="card"><view class="types"><view :class="{ selected: serviceType==='repair' }" @tap="serviceType='repair'">维修</view><view :class="{ selected: serviceType==='replacement' }" @tap="serviceType='replacement'">置换</view></view><textarea v-model="description" maxlength="500" placeholder="请说明剪刀问题、使用情况与处理诉求"/><view class="address-title"><text>维修完成后的收货地址</text><text @tap="manageAddress">管理地址</text></view><view v-if="!addresses.length" class="address-empty" @tap="manageAddress">请先新增收货地址</view><view v-for="item in addresses" :key="item.id" class="address" :class="{ selected:Number(selectedAddressId)===Number(item.id) }" @tap="selectAddress(item)"><view><text>{{ item.name||item.contact }}</text><text>{{ item.phone }}</text></view><text>{{ fullAddress(item) }}</text></view><button class="submit" :class="{ disabled:submitting }" @tap="submit">{{ submitting?'提交中...':'提交申请' }}</button><text class="ui-small hint">审核通过后会提供寄回地址。寄出快递费请您先行垫付并保留凭证；维修完成并寄回后，将按售后规则补发运费抵扣券，具体以到账券面为准。</text></view><view v-if="pendingShipment" class="card shipment"><text class="ui-strong">填写寄回物流</text><text>寄回地址：{{ pendingShipment.serviceAddress||'请等待售后专员补充地址' }}</text><input v-model="shipment.carrier" placeholder="快递公司"/><input v-model="shipment.trackingNo" placeholder="快递单号"/><input v-model="shipment.freightAmount" type="digit" placeholder="实际寄出运费（元）"/><button class="submit" @tap="submitShipment">提交寄回物流</button></view><text class="heading">售后记录</text><view v-if="!records.length" class="state">暂无售后记录</view><view v-for="item in records" :key="item.id" class="card record"><view><text class="ui-strong">{{ item.serviceTypeText }}</text><text class="ui-strong">{{ item.statusText }}</text></view><text>{{ item.issue_description }}</text><text class="ui-small">{{ item.createdAtText }}</text><text v-if="item.return_tracking_no">寄回物流：{{ item.return_carrier }} {{ item.return_tracking_no }}</text><text v-if="item.outbound_tracking_no">回寄物流：{{ item.outbound_carrier }} {{ item.outbound_tracking_no }}</text><text v-if="item.freight_coupon_status==='issued'" class="coupon">运费抵扣券已补发：{{ item.freight_coupon_note||'请前往优惠券查看' }}</text><view v-if="item.messages.length" class="messages"><view v-for="message in item.messages" :key="message.id" :class="{ seller:message.isSeller }"><text class="ui-small">{{ message.senderText }}　{{ message.createdAtText }}</text><text>{{ message.content }}</text></view></view><text class="ui-small" v-else>售后专员暂未留言，请耐心等待。</text></view></view></scroll-view>
</template>
<script>
import api from '../../common/api.js'
const services={repair:'申请维修',replacement:'申请置换'}, statuses={submitted:'待受理',awaiting_shipment:'待寄回',shipped:'已寄回，待收件',received:'已收件',inspecting:'检测中',accepted:'已受理',repairing:'维修中',replacement_pending:'待置换',awaiting_user:'待您确认',returning:'待寄回用户',completed:'已完成',rejected:'未受理',cancelled:'已取消'}
const date=value=>{if(!value)return'—';const m=String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[1]}年${m[2]}月${m[3]}日`:String(value)};const time=value=>value?String(value).replace('T',' ').slice(0,16):''
export default { data(){return{bindingId:0,scissors:null,records:[],addresses:[],selectedAddressId:0,serviceType:'repair',description:'',shipment:{carrier:'',trackingNo:'',freightAmount:''},pendingShipment:null,loading:true,submitting:false}},onLoad(options){this.bindingId=Number(options.bindingId)||0;if(this.bindingId)this.load();else uni.showToast({title:'剪刀信息无效',icon:'none'})},onShow(){if(this.loaded&&this.bindingId)this.load()},methods:{fullAddress:item=>`${item.province||''}${item.city||''}${item.district||''}${item.detail||''}`,async load(){this.loading=true;try{const[data,addressData]=await Promise.all([api.getScissorsAfterSale(this.bindingId),api.getAddressList()]);const rows=api.asList(addressData);const selected=rows.find(item=>Number(item.id)===Number(this.selectedAddressId))||rows.find(item=>Number(item.is_default)===1)||rows[0]||null;this.addresses=rows;this.selectedAddressId=selected&&selected.id||0;const sc=data.scissors||{};this.scissors={...sc,modelText:sc.spec_name||sc.model||'专业美容工具',activationText:date(sc.activation_date),warrantyText:sc.activation_date&&sc.warranty_expire?`${date(sc.activation_date)} 至 ${date(sc.warranty_expire)}`:sc.warranty_expire?date(sc.warranty_expire):(sc.warranty_months?`${sc.warranty_months}个月`:'—')};this.records=(data.records||[]).map(item=>({...item,serviceTypeText:services[item.service_type]||'售后申请',statusText:statuses[item.status]||item.status||'处理中',createdAtText:time(item.created_at),canShip:item.status==='awaiting_shipment',serviceAddress:item.service_address_text||'',messages:(item.messages||[]).map(message=>({...message,isSeller:message.sender_role==='seller',senderText:message.sender_role==='seller'?'售后专员':'您',createdAtText:time(message.created_at)}))}));this.pendingShipment=this.records.find(item=>item.canShip)||null}catch(error){uni.showToast({title:error.message||'加载售后信息失败',icon:'none'})}finally{this.loading=false;this.loaded=true}},selectAddress(item){this.selectedAddressId=item.id},manageAddress(){uni.navigateTo({url:'/pages/address-manage/index'})},async submit(){const text=this.description.trim();if(text.length<5)return uni.showToast({title:'请至少说明 5 个字的问题',icon:'none'});if(!this.selectedAddressId)return uni.showToast({title:'请先选择维修完成后的收货地址',icon:'none'});if(this.submitting)return;this.submitting=true;try{await api.applyScissorsAfterSale({bindingId:this.bindingId,serviceType:this.serviceType,description:text,recipientAddressId:this.selectedAddressId});this.description='';uni.showToast({title:'申请已提交',icon:'success'});this.load()}catch(error){uni.showToast({title:error.message||'提交失败',icon:'none'})}finally{this.submitting=false}},async submitShipment(){const data=this.shipment;if(!this.pendingShipment)return;if(!data.carrier.trim()||!data.trackingNo.trim()||data.freightAmount==='')return uni.showToast({title:'请填写快递公司、单号和实际运费',icon:'none'});try{await api.submitScissorsAfterSaleShipping({requestId:this.pendingShipment.id,carrier:data.carrier.trim(),trackingNo:data.trackingNo.trim(),freightAmount:Number(data.freightAmount)});uni.showToast({title:'物流信息已提交',icon:'success'});this.shipment={carrier:'',trackingNo:'',freightAmount:''};this.load()}catch(error){uni.showToast({title:error.message||'提交失败',icon:'none'})}}}}
</script>
<style>
.page{height:100vh;padding:14px;box-sizing:border-box;background:#F4F6F8}.state{padding:48px 0;color:#636366;text-align:center;font-size:14px}.hero{display:flex;align-items:center;flex-direction:column;padding:15px 12px 25px}.hero image{width:132px;height:132px;border-radius:20px;background:#fff;box-shadow:0 6px 16px rgba(29,29,31,.06)}.hero .ui-strong{margin-top:13px;font-size:21px}.hero text{margin-top:5px;color:#636366;font-size:14px}.heading{display:block;margin:22px 2px 8px;font-size:17px;font-weight:700}.card{padding:14px;border-radius:13px;background:#fff;box-shadow:0 4px 14px rgba(29,29,31,.05)}.archive>view,.record>view:first-child{display:flex;align-items:center;justify-content:space-between;padding:9px 0;border-bottom:1px solid #eee;font-size:13px}.archive>view text:first-child{font-weight:500}.archive>view text:last-child{color:#636366;text-align:right}.archive>view:last-child .ui-strong{color:#0B0D10}.types{display:flex;gap:9px}.types>view{flex:1;padding:10px;border:1px solid #eee;border-radius:8px;color:#636366;text-align:center;font-size:14px}.types>view.selected{border-color:#0B0D10;background:#0B0D10;color:#fff}.card textarea{width:100%;height:105px;margin-top:12px;padding:10px;box-sizing:border-box;border-radius:8px;background:#F4F6F8;font-size:13px}.address-title{display:flex;justify-content:space-between;margin-top:12px;font-size:13px;font-weight:650}.address-title text:last-child{color:#0B0D10;font-weight:400}.address,.address-empty{margin-top:8px;padding:9px;border-radius:7px;background:#F4F6F8;color:#636366;font-size:12px;line-height:1.5}.address.selected{border:1px solid #0B0D10;background:#F4F7FA}.address>view{display:flex;gap:9px;color:#0B0D10}.submit{margin-top:12px;border-radius:20px;background:#0B0D10;color:#fff;font-size:14px;line-height:41px}.submit::after{border:0}.submit.disabled{opacity:.55}.hint,.record .ui-small{display:block;margin-top:8px;color:#636366;font-size:11px;line-height:1.5}.shipment{margin-top:13px}.shipment>.ui-strong,.shipment>text{display:block}.shipment>text{margin-top:7px;color:#636366;font-size:12px}.shipment input{height:39px;margin-top:8px;padding:0 9px;border-radius:7px;background:#F4F6F8;font-size:13px}.record{margin-bottom:10px}.record>text{display:block;margin-top:8px;font-size:13px;line-height:1.5}.record>text.coupon{color:#0B0D10}.record>view:first-child .ui-strong:last-child{color:#0B0D10}.messages{margin-top:10px;padding-top:9px;border-top:1px solid #eee}.messages>view{margin-top:7px;padding:8px;border-radius:7px;background:#F4F6F8}.messages>view.seller{background:#F4F7FA}.messages text{display:block;margin-top:5px;font-size:12px;line-height:1.5}
</style>
